<?php require_once __DIR__.'/includes/admin_auth_check.php';require_once __DIR__.'/../config/db.php';$rows=[];$total=0;try{$p=db();$total=(float)$p->query("SELECT COALESCE(SUM(amount),0) FROM payments WHERE status='success'")->fetchColumn();$rows=$p->query('SELECT p.*,u.full_name student FROM payments p JOIN users u ON u.id=p.student_id ORDER BY p.created_at DESC')->fetchAll();}catch(Throwable $e){}$pageTitle='Payments';require __DIR__.'/../includes/header.php';?><main class="container py-5"><h1 class="h2">Payments</h1><div class="profile-section mb-3">Total revenue: <strong>৳<?=number_format($total,2)?></strong></div><table class="table"><tr><th>Student</th><th>Amount</th><th>Method</th><th>Status</th><th>Date</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['student'])?></td><td>৳<?=e($r['amount'])?></td><td><?=e($r['method'])?></td><td><?=e($r['status'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table></main>
